using WPods.Service;
using System.Buffers.Binary;
int checks=0;
void Check(bool ok,string label){if(!ok)throw new Exception(label);checks++;}
byte[] Signal(byte code,byte id,params byte[] data){byte[] p=new byte[4+data.Length];p[0]=code;p[1]=id;BinaryPrimitives.WriteUInt16LittleEndian(p.AsSpan(2),(ushort)data.Length);data.CopyTo(p,4);return p;}
DirectMouseHid Open(){
 var h=new DirectMouseHid();h.Start(0);Check(h.TakeOutput().Count==0,"Mouse gets the first chance to reconnect");h.Tick(500);var connect=h.TakeOutput().Single();
 Check(connect.Cid==1&&connect.Payload[0]==2&&connect.Payload[4]==0x11,"Control PSM requested first");
 h.SignalInput(Signal(3,connect.Payload[1],0x40,0,0xC0,0x7F,0,0,0,0),501);
 var config=h.TakeOutput().Single();Check(config.Payload[0]==4&&config.Payload[4]==0x40,"Configure remote control CID");
 var longReply=Signal(5,config.Payload[1],0xC0,0x7F,0,0,0,0,1,2,0,2);
 Check(h.OwnSignal(longReply.AsSpan(0,12),prefix:true),"Partial routing header recognizes a longer configuration response");
 Check(!h.OwnSignal(longReply.AsSpan(0,12)),"Full-message validation still rejects a truncated response");
 h.SignalInput(Signal(4,0x30,0xC0,0x7F,0,0,1,2,0xA0,2),502);
 var reply=h.TakeOutput().Single();Check(reply.Payload[0]==5&&reply.Payload[8]==0,"Accept peer basic MTU");
 h.SignalInput(Signal(5,config.Payload[1],0xC0,0x7F,0,0,0,0),503);
 Check(h.TakeOutput().Count==0,"No interrupt-channel race with the mouse");h.Tick(1003);
 var interrupt=h.TakeOutput().Single();Check(interrupt.Payload[0]==2&&interrupt.Payload[4]==0x13,"Interrupt PSM follows configured control channel");
 h.SignalInput(Signal(3,interrupt.Payload[1],0x41,0,0xC1,0x7F,0,0,0,0),1004);
 config=h.TakeOutput().Single();h.SignalInput(Signal(4,0x31,0xC1,0x7F,0,0),1005);h.TakeOutput();
 h.SignalInput(Signal(5,config.Payload[1],0xC1,0x7F,0,0,0,0),1006);
 var setup=h.TakeOutput();Check(setup.Count==2&&setup[0].Payload.SequenceEqual(new byte[]{0x14})&&setup[1].Payload.SequenceEqual(new byte[]{0x71}),"Wake and report-protocol setup precede the feature");
 h.Data(0x7FC0,new byte[]{0},1007);
 var feature=h.TakeOutput().Single();Check(feature.Cid==0x40&&feature.Payload.SequenceEqual(new byte[]{0x53,0xF1,2,1}),"One explicit feature activation on the configured control channel");
 return h;
}
var mouse=Open();Check(!mouse.Ready,"Open channels alone are not readiness");
mouse.Data(0x7FC0,new byte[]{0},1008);Check(mouse.Ready&&!mouse.Failed,"Successful HIDP handshake");
mouse.Data(0x7FC1,new byte[]{0xA1,0x12,0,1,0,2,0,0,0},1009);Check(mouse.InputReports==1,"Validated compact input counted");
mouse.Data(0x7FC1,new byte[]{0xA1,0x12},1010);Check(mouse.InputReports==1,"Truncated input rejected");
Check(!mouse.OwnCid(0x40)&&!mouse.OwnSignal(Signal(4,0x10,0x40,0,0,0)),"Other channels untouched");
mouse.SignalInput(Signal(6,0x33,0xC1,0x7F,0x41,0),1011);Check(mouse.Failed&&!mouse.Ready,"Peer disconnect ends readiness");
var closed=mouse.TakeOutput().Single();Check(closed.Payload[0]==7,"Peer disconnect acknowledged");
mouse.Data(0x7FC0,new byte[]{0},1012);Check(!mouse.Ready,"Late data cannot resurrect a closed channel");
mouse=Open();mouse.Data(0x7FC0,new byte[]{0},5000);Check(mouse.Failed&&!mouse.Ready,"Late handshake cannot establish readiness");
mouse=Open();mouse.Data(0x7FC0,new byte[]{2},1008);
Check(!mouse.Ready&&!mouse.Failed&&mouse.TakeOutput().Count==0,"Known INVALID_REPORT_ID quirk does not close the connection or invent readiness");
mouse.Tick(1507);Check(mouse.TakeOutput().Count==0,"Deferred retry waits 500ms");mouse.Tick(1508);
Check(mouse.TakeOutput().Single().Payload.SequenceEqual(new byte[]{0x53,0xF1,2,1}),"Retry uses known compact activation exactly once");
mouse.Data(0x7FC0,new byte[]{2},1509);mouse.Tick(12000);
Check(!mouse.Failed&&!mouse.Ready&&mouse.TakeOutput().Count==0,"Keep paired mouse channels alive while awaiting physical touch");
var full=new byte[15];full[0]=0xA1;full[1]=0x12;mouse.Data(0x7FC1,full,12001);
Check(mouse.Ready&&!mouse.Failed,"A real full report proves the mode switch despite the misleading handshake");
mouse=new();mouse.Start(0);
mouse.SignalInput(Signal(2,1,0x11,0,0x60,0),10);
var accepted=mouse.TakeOutput();Check(accepted.Count==2&&accepted[0].Payload[0]==3&&accepted[0].Payload[8]==0,"Accept the real device-initiated control channel");
byte configId=accepted[1].Payload[1];mouse.SignalInput(Signal(4,2,0xC0,0x7F,0,0),20);mouse.TakeOutput();
mouse.SignalInput(Signal(5,configId,0xC0,0x7F,0,0,0,0),30);Check(mouse.TakeOutput().Count==0,"Configured control waits for device-initiated interrupt channel");
mouse.SignalInput(Signal(2,3,0x13,0,0x61,0),40);accepted=mouse.TakeOutput();configId=accepted[1].Payload[1];
Check(accepted.Count==2&&accepted[0].Payload[0]==3&&accepted[0].Payload[8]==0,"Accept device-initiated interrupt channel");
mouse.SignalInput(Signal(4,4,0xC1,0x7F,0,0),50);mouse.TakeOutput();mouse.SignalInput(Signal(5,configId,0xC1,0x7F,0,0,0,0),60);
Check(mouse.TakeOutput().Count==2,"Device-initiated channels reach protocol initialization without duplicate opens");
mouse.Data(0x7FC0,new byte[]{3},61);Check(mouse.TakeOutput().Single().Payload[0]==0x53,"A report-only device can decline SET_PROTOCOL without blocking touch activation");
Check(mouse.ReleaseForPeer()&&mouse.Released&&!mouse.Ready,"Explicit host handoff marks the channel released");
var release=mouse.TakeOutput().Single();Check(release.Payload.SequenceEqual(new byte[]{0x15}),"Host handoff sends HID virtual-cable unplug rather than adapter power changes");
mouse.Tick(100000);mouse.Data(0x7FC0,new byte[]{0},100001);Check(!mouse.Ready&&mouse.TakeOutput().Count==0,"Released channels cannot resume input or touch retries");
Check(mouse.ReleaseForPeer()&&mouse.TakeOutput().Count==0,"Repeated host release is idempotent");
mouse=new();mouse.Start(0);mouse.TakeOutput();mouse.Tick(10001);Check(mouse.Failed,"Bounded open timeout");
var random=new Random(63);for(int i=0;i<10000;i++){var p=new byte[random.Next(0,200)];random.NextBytes(p);mouse.OwnSignal(p);mouse.SignalInput(p,11000+i);mouse.Data(0x7FC1,p,11000+i);}checks++;
mouse=Open();mouse.Data(0x7FC0,new byte[]{0},1008);mouse.Tick(1010);
Check(mouse.TakeOutput().Single().Payload.SequenceEqual(new byte[]{0x41,0x90}),"Battery is requested as input report 0x90 after touch initialization");
mouse.Data(0x7FC0,new byte[]{0xA1,0x90,4,95},1011);
Check(mouse.BatteryPercent==95&&mouse.BatterySequence==1&&mouse.Ready&&!mouse.Failed,"Capacity is decoded after flags, without disrupting touch");
mouse.Tick(2000);Check(mouse.TakeOutput().Count==0,"Battery polling is bounded to once per minute");
mouse.Tick(61010);Check(mouse.TakeOutput().Single().Payload.SequenceEqual(new byte[]{0x41,0x90}),"A connected mouse refreshes battery without reconnecting");
mouse.Data(0x7FC0,new byte[]{0xA1,0x90,4,255},61011);Check(mouse.BatteryPercent==95&&mouse.BatterySequence==1,"Unknown battery sentinel does not overwrite the last real reading");
mouse.Tick(121010);mouse.TakeOutput();mouse.Data(0x7FC0,new byte[]{2},121011);
Check(mouse.Ready&&!mouse.Failed,"Unsupported battery query cannot disable the input channel");
mouse.Tick(181010);mouse.TakeOutput();mouse.Data(0x7FC1,new byte[]{0xA1,0x90,4,30},181011);
Check(mouse.BatterySequence==1,"An unsolicited report on another channel is not a query response");
mouse.Data(0x7FC0,new byte[]{0xA1,0x90,4},181012);Check(mouse.BatterySequence==1,"Truncated battery responses are rejected");
mouse.ReleaseForPeer();mouse.TakeOutput();mouse.Tick(241010);mouse.Data(0x7FC0,new byte[]{0xA1,0x90,4,29},241011);
Check(mouse.TakeOutput().Count==0&&mouse.BatterySequence==1,"Released mouse never polls or republishes old responses");
Console.WriteLine($"PASS {checks} direct-HID checks including battery protocol and 10000 malformed packets; no Bluetooth hardware accessed");
